) AS (
  VALUES 
    (607::BIGINT, 'Es bastante duro si uno no tiene buenas bases, pero en realidad es excelente profesor y si muestra interés en el curso el le ayuda. Explica muy a profundidad y por eso muchos se pierden.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'f26cc5a2613b4e7891214e1b7214bf4c9b048fa3243efcb5d3da20025c0aa9ea'::TEXT, ARRAY[1631, 1629]::BIGINT[]),
    (607::BIGINT, 'Excelente profesor, exigente como su calidad, pone suficientes ejemplos y pone muchísima práctica, las consultas son bien abarcadas y si demuestra interés el profesor facilita el aprendizaje muchísimo, mi mejor profesor de matemática en toda la vida'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-23T00:00:00+00:00'::TIMESTAMPTZ, '31c7ff61cf94444fefaba79ba9673824f50be961ca2e74b22952bf3929b775c9'::TEXT, ARRAY[605]::BIGINT[]),
    (607::BIGINT, 'Fácilmente el peor profesor del TEC y un viejo verde'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '4049b9bbe6fdca317037c3b7b0ddc3dd21b54b191a94073e9e67ecf43cbc7594'::TEXT, ARRAY[563]::BIGINT[]),
    (607::BIGINT, 'Tremendo viejo verde, si no es mujer mejor ni trate de hablarle.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2024-03-12T00:00:00+00:00'::TIMESTAMPTZ, '4171a2a95528354d04ca7a23ef87af020e1337725657a635180f3f8300de644f'::TEXT, ARRAY[605]::BIGINT[]),
    (607::BIGINT, 'Siempre he creído que sobreestima su intelecto y sus capacidades lógico-matemáticas. Además, carece de empatía y sus habilidades blandas son bastante cuestionables. No digo que sea mal matemático, es muy buen matemático, pero sus habilidades pedagógicas, para mi, son algo limitadas.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2024-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'c7f05dcdc80561693d7b352a3af70d5063fc9d5040d8f42e0042d4b467c887b1'::TEXT, ARRAY[563, 564]::BIGINT[]),
    (607::BIGINT, 'un pelado sobon'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, '75e19629fd110608e5c2fce9c20eba1ecd2992322c2c27d68e1e523bcf8efa58'::TEXT, ARRAY[1034]::BIGINT[]),
    (607::BIGINT, 'Cuesta demasiado entenderlo y es fácil perderse en lo que explica, sus clases son confusas y lentas. En sus evaluaciones un error pequeño lo castiga de manera muy estricta.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2023-11-29T00:00:00+00:00'::TIMESTAMPTZ, '46989276400cfa130de8d749b415d4868e1d57ccaa297c29097076ace4635e8d'::TEXT, ARRAY[605]::BIGINT[]),
    (607::BIGINT, 'Sinceramente me parece buen profesor si uno llega con buenas bases para la materia o si lo está repitiendo. Si califica bastante duro en los parciales, pero en terminos de quizzes si uni hace las prácticas que él manda le puede ir bastante bien.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico']::TEXT[], '2023-11-17T00:00:00+00:00'::TIMESTAMPTZ, '0dc05b152a55e72febc8040c1b97a7ab670d5c0e562e037ce1ffeac521b6bde5'::TEXT, ARRAY[605]::BIGINT[]),
    (607::BIGINT, 'Si usted lleva el curso por primera vez, va a ser confuso y demasiado difícil porque él explica para las personas que ya han llevado el curso antes, no desde 0. No pienso que él tenga favoritismo con las mujeres, sino que con ambos (hombres y mujeres) es igual. Casi no ayuda con las dudas.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2023-10-26T00:00:00+00:00'::TIMESTAMPTZ, '0a40902b8c1e3e363831f08c710bb3ac4014433b30e16c16a007bdfadd674183'::TEXT, ARRAY[605]::BIGINT[]),
    (607::BIGINT, 'Sus clases son complicadas y cuesta entenderle, tiende a brindar poca ayuda, por lo que kas evaluaciones se te van a complicar.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2023-10-21T00:00:00+00:00'::TIMESTAMPTZ, '5af7bf23dc75901d24d9fe4202a28338965c84fbff1f289491d434b155bc8872'::TEXT, ARRAY[605]::BIGINT[]),
    (607::BIGINT, 'A mi criterio es un pésimo profesor sus clases se sienten sin compromiso, solo se entusiasma ayudando a las estudiantes femeninas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-08-30T00:00:00+00:00'::TIMESTAMPTZ, 'c6f5e0ac0bdcbd5344c142479ea65a5a3a9ba71579eafb007bfb97f2e3156277'::TEXT, ARRAY[605]::BIGINT[]),
    (607::BIGINT, 'Pésimo profesor, tiende a favorecer a las estudiantes mujeres y otros que le caen bien, sino tiene amistad prepárese para sufrir'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil']::TEXT[], '2023-08-19T00:00:00+00:00'::TIMESTAMPTZ, '01185b12fb086072bc12a23e971ba9651626e714f11fda8522129cd8bb1d0561'::TEXT, ARRAY[605]::BIGINT[]),
    (607::BIGINT, 'Eviten matricular con él, es pésimo como profesor no sabe enseñar, por lo menos ya no tiene muchos cursos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'd03fee3e55b1d0c11d826bf6ba05c397f8422e1ae643525931c0d913b19ea66d'::TEXT, ARRAY[605]::BIGINT[]),
    (607::BIGINT, 'Con todo el respeto que se merece, no lo considero un buen profesor, explica rápido y sus clases son confusas, lo que genera dudas y a la hora de consultar las dudas las responde de mala gana.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Asistencia obligatoria']::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, '6687bb6ad941e714e0d310291bcda3645794c02e6ffa676a5c10bd63458f4630'::TEXT, ARRAY[605]::BIGINT[]),
    (607::BIGINT, 'Un profe sin pelos en la lengua, todas sus clases me encandilaba con su conocimiento, solo no se sienten al frente porque quedan ciegos'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Inspirador']::TEXT[], '2022-08-10T00:00:00+00:00'::TIMESTAMPTZ, '5913e65e9d799738727db974c3aa95fd51fb6c0bcb5923a26b62a3712429fbc3'::TEXT, ARRAY[1632]::BIGINT[]),
    (607::BIGINT, 'Ojala nunca tengan que pedirle ayuda'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2022-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'd2079e9e9111afe0695e2cb6d978594609cd17c26cfdd2ba182ae248ba12caf4'::TEXT, ARRAY[1631, 1629]::BIGINT[]),
    (607::BIGINT, 'Es un profesor que tiene una marcada preferencia para favorecer estudiantes mujeres, y algunos otros que le agraden, lo cual se nota mucho. Sus clases son regulares, aunque esa manera de actuar hacía las estudiantes es muy desagradable para mí.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Da crédito extra']::TEXT[], '2022-01-12T00:00:00+00:00'::TIMESTAMPTZ, '45c5c310bb93c6ab9744c2819ece56580577d11d5426bd07a02797eca00cf068'::TEXT, ARRAY[563, 564]::BIGINT[]),
    (607::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2022-01-09T00:00:00+00:00'::TIMESTAMPTZ, '4a0c178f96495aa5eac24fca247b7322c8de1b00b006d5d567d40db177b76d70'::TEXT, ARRAY[563, 564]::BIGINT[]),
    (607::BIGINT, 'El mae explica muy rápido, tuve de nota un 67,40 le pedí que si me daba un trabajo o tarea extra (hasta si me regalaba el 0,10), pero como no soy una mujer, no me lo dio, ya una compañera estaba igual que yo y si le dio el trabajo extra, así que se nota lo viejo verde que es.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, '267c5d600a9441d2c9dbe51fd0052fb7ba9bfe665c6e0a9a620ec2628ebc50ca'::TEXT, ARRAY[563, 564]::BIGINT[]),
    (607::BIGINT, 'A la hora de explicar es regular, responde dudas a veces y de mala gana. Fue director de la escuela de matemática, aunque eso es solo un título que le gusta poner al final de los correos.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, '5c5ef49df9e501cce0bb14c851261fcd3eedf103b949433d4a5f4279f605d09d'::TEXT, ARRAY[563, 564]::BIGINT[]),
    (607::BIGINT, 'Explica muy rápido pero se le entiende bien. Suele hacer preguntas directas a los estudiantes, pero no toma en cuenta si no se le contesta. En telegram responde muy rápido las dudas. No es muy cálido pero no es malo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '203907060f56b6e9d6343b6b1df3d0a8423cc3bf7e00fae6665036b7d19ef90b'::TEXT, ARRAY[563]::BIGINT[]),
    (607::BIGINT, 'No es el mejor ni tampoco el peor. A veces va demasiado rápido. Está atento a las consultas que se tengan.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, '52ed6eb3fa35194564a7b1c1bc9baf4c8e274ae653d7627f42ef20ca6c86d8c2'::TEXT, ARRAY[563]::BIGINT[]),
